import React, { useState } from "react";
import Login from "./Login";
import Register from "./Register";
import History from "./History";
import "./App.css";

function App() {
  const [selectedFile, setSelectedFile] = useState(null);
  const [previewUrl, setPreviewUrl] = useState(null);
  const [results, setResults] = useState(null);
  const [loading, setLoading] = useState(false);
  const [currentPage, setCurrentPage] = useState("main");
  const [authToken, setAuthToken] = useState(null);
  const [userEmail, setUserEmail] = useState("");

  const handleLoginSuccess = (token, email) => {
    setAuthToken(token);
    setUserEmail(email);
    setCurrentPage("main");
  };

  const handleLogout = () => {
    setAuthToken(null);
    setUserEmail("");
    setSelectedFile(null);
    setPreviewUrl(null);
    setResults(null);
  };

  const handleFileSelect = (event) => {
    const file = event.target.files[0];
    if (file) {
      setSelectedFile(file);
      const url = URL.createObjectURL(file);
      setPreviewUrl(url);
      setResults(null);
    }
  };

  const analyzeFood = async () => {
    if (!selectedFile) {
      alert("Te rog selectează o imagine mai întâi!");
      return;
    }

    setLoading(true);
    const formData = new FormData();
    formData.append("file", selectedFile);

    try {
      const headers = {};
      // Add user email to headers if authenticated
      if (authToken && userEmail) {
        headers['X-User-Email'] = userEmail;
      }

      const res = await fetch("http://127.0.0.1:8001/analyze_food/", {
        method: "POST",
        headers: headers,
        body: formData,
      });
      const data = await res.json();
      setResults(data);

      // Show success message if analysis was saved
      if (data.analysis_id) {
        console.log("✅ Analysis saved to database with ID:", data.analysis_id);
      }
    } catch (error) {
      console.error("Error analyzing food:", error);
      alert("Eroare la analizarea imaginii. Asigură-te că backend-ul rulează!");
    } finally {
      setLoading(false);
    }
  };

  const renderPage = () => {
    switch (currentPage) {
      case "login":
        return <Login onBack={() => setCurrentPage("main")} onLoginSuccess={handleLoginSuccess} onNavigateToRegister={() => setCurrentPage("register")} />;
      case "register":
        return <Register onBack={() => setCurrentPage("main")} onRegisterSuccess={() => setCurrentPage("login")} onNavigateToLogin={() => setCurrentPage("login")} />;
      case "history":
        return <History userEmail={userEmail} onBack={() => setCurrentPage("main")} />;
      default:
        return (
          <div className="animated-bg" style={{ minHeight: "100vh" }}>
            {/* Header */}
            <header className="header">
              <div className="header-content">
                <div className="logo" onClick={() => setCurrentPage("main")} style={{ cursor: "pointer" }}>
                  🍳 SmartChef
                </div>
                <div className="nav-buttons">
                  {authToken ? (
                    <>
                      <button
                        className="btn btn-outline"
                        onClick={() => setCurrentPage("history")}
                        style={{ marginRight: "1rem" }}
                      >
                        📊 Istoric
                      </button>
                      <span style={{ color: "white", marginRight: "1rem", fontWeight: "500" }}>
                        👤 {userEmail}
                      </span>
                      <button
                        className="btn btn-outline"
                        onClick={handleLogout}
                      >
                        Logout
                      </button>
                    </>
                  ) : (
                    <>
                      <button
                        className="btn btn-outline"
                        onClick={() => setCurrentPage("login")}
                      >
                        Login
                      </button>
                      <button
                        className="btn btn-secondary"
                        onClick={() => setCurrentPage("register")}
                      >
                        Register
                      </button>
                    </>
                  )}
                </div>
              </div>
            </header>

            {/* Main Content Container */}
            <div style={{ maxWidth: "1200px", margin: "0 auto", padding: "3rem 2rem" }}>
              {/* Hero Section - Only show when not authenticated */}
              {!authToken && (
                <>
                  <div style={{ textAlign: "center", marginBottom: "3rem" }}>
                  <h1 style={{ 
                    fontSize: "3.5rem", 
                    fontWeight: "800", 
                    color: "#ff6b35",
                    marginBottom: "1rem",
                    textShadow: "2px 2px 4px rgba(0,0,0,0.1)"
                  }}>
                    ✨ Bine ai venit la SmartChef! ✨
                  </h1>
                  <p style={{ 
                    fontSize: "1.3rem", 
                    color: "#666",
                    fontWeight: "400"
                  }}>
                    Analiză inteligentă a alimentelor cu AI și valori nutriționale
                  </p>
                </div>

                {/* Feature Cards */}
                <div style={{ 
                  display: "grid", 
                  gridTemplateColumns: "repeat(auto-fit, minmax(300px, 1fr))", 
                  gap: "2rem",
                  marginBottom: "3rem"
                }}>
                  <div className="feature-card">
                    <div className="feature-icon">🔍</div>
                    <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
                      Recunoaștere AI
                    </h3>
                    <p style={{ color: "#666", lineHeight: "1.6" }}>
                      Detectează automat ingredientele din fotografii folosind inteligență artificială
                    </p>
                  </div>

                  <div className="feature-card">
                    <div className="feature-icon">📊</div>
                    <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
                      Valori Nutriționale
                    </h3>
                    <p style={{ color: "#666", lineHeight: "1.6" }}>
                      Calculează automat calorii, proteine, carbohidrați și alte valori
                    </p>
                  </div>

                  <div className="feature-card">
                    <div className="feature-icon">🔒</div>
                    <h3 style={{ fontSize: "1.4rem", marginBottom: "0.8rem", color: "#333" }}>
                      Securitate 2FA
                    </h3>
                    <p style={{ color: "#666", lineHeight: "1.6" }}>
                      Contul tău este protejat cu autentificare în doi pași
                    </p>
                  </div>
                </div>
              </>
            )}

              {/* Upload Section - Only for authenticated users */}
              {!authToken ? (
                <div className="card" style={{ maxWidth: "600px", margin: "0 auto", textAlign: "center" }}>
                  <h2 style={{ fontSize: "2rem", color: "#ff6b35", marginBottom: "1rem" }}>
                    🔒 Autentificare Necesară
                  </h2>
                  <p style={{ fontSize: "1.1rem", color: "#666", marginBottom: "2rem" }}>
                    Te rog să te autentifici pentru a folosi funcția de analiză alimentară
                  </p>
                  <div style={{ display: "flex", gap: "1rem", justifyContent: "center" }}>
                    <button
                      className="btn btn-primary"
                      onClick={() => setCurrentPage("login")}
                      style={{ padding: "1rem 2rem" }}
                    >
                      🔐 Login
                    </button>
                    <button
                      className="btn btn-secondary"
                      onClick={() => setCurrentPage("register")}
                      style={{ padding: "1rem 2rem" }}
                    >
                      📝 Înregistrare
                    </button>
                  </div>
                </div>
              ) : (
                <div className="card" style={{ maxWidth: "800px", margin: "0 auto" }}>
                  <h2 style={{ 
                    fontSize: "2rem", 
                    marginBottom: "2rem", 
                    color: "#ff6b35",
                    textAlign: "center",
                    fontWeight: "700"
                  }}>
                    📸 Încarcă o imagine cu mâncare
                  </h2>

                  <input
                    id="file-upload"
                    type="file"
                    accept="image/*"
                    onChange={handleFileSelect}
                    style={{ display: "none" }}
                  />

                  {!previewUrl ? (
                    <label htmlFor="file-upload" className="upload-area">
                      <div className="upload-icon">📁</div>
                      <p style={{ fontSize: "1.1rem", color: "#666", marginBottom: "0.5rem" }}>
                        Click pentru a selecta o imagine
                      </p>
                      <p style={{ fontSize: "0.9rem", color: "#999" }}>
                        Acceptăm JPG, PNG, JPEG
                      </p>
                    </label>
                  ) : (
                    <div>
                      <div className="image-preview">
                        <img src={previewUrl} alt="Food preview" />
                      </div>
                      <label htmlFor="file-upload">
                        <div style={{
                          textAlign: "center",
                          marginTop: "1rem",
                          cursor: "pointer",
                          color: "#ff6b35",
                          fontWeight: "600",
                          fontSize: "1rem"
                        }}>
                          🔄 Schimbă imaginea
                        </div>
                      </label>
                    </div>
                  )}

                  <button
                    className="btn btn-primary"
                    onClick={analyzeFood}
                    disabled={loading || !selectedFile}
                    style={{
                      width: "100%",
                      padding: "1.2rem",
                      fontSize: "1.1rem",
                      marginTop: "1.5rem",
                      opacity: loading || !selectedFile ? 0.6 : 1,
                      cursor: loading || !selectedFile ? "not-allowed" : "pointer"
                    }}
                  >
                    {loading ? "🔄 Se analizează..." : "🔍 Analizează Alimentul"}
                  </button>

                  {loading && <div className="spinner"></div>}

                  {results && results.status === "success" && (
                    <div className="results-container">
                      <div className="results-header">
                        ✅ Rezultate Analiză
                      </div>

                      {results.analysis_id && (
                        <p style={{ 
                          textAlign: "center", 
                          color: "#4CAF50", 
                          fontSize: "0.9rem",
                          marginBottom: "1rem",
                          fontWeight: "600"
                        }}>
                          💾 Analiza a fost salvată în istoric!
                        </p>
                      )}

                      <div style={{ marginBottom: "2rem" }}>
                        <h3 style={{ fontSize: "1.3rem", marginBottom: "1rem", color: "#2e7d32" }}>
                          🥗 Ingrediente Detectate ({results.ingredients.length}):
                        </h3>
                        <div>
                          {results.ingredients.map((ingredient, index) => (
                            <span key={index} className="ingredient-badge">
                              {ingredient}
                            </span>
                          ))}
                        </div>
                      </div>

                      <div className="nutrition-box">
                        <h3 style={{ fontSize: "1.3rem", marginBottom: "1.5rem", color: "#ff6b35", textAlign: "center" }}>
                          📊 Valori Nutriționale Totale
                        </h3>

                        {/* Progress Bars pentru nutriție */}
                        <div style={{ marginBottom: "1.5rem" }}>
                          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                            <span style={{ fontSize: "1rem", fontWeight: "600", color: "#333" }}>🔥 Calorii</span>
                            <span style={{ fontSize: "1.1rem", fontWeight: "700", color: "#ff6b35" }}>
                              {results.nutrition.total_calories} kcal
                            </span>
                          </div>
                          <div style={{ 
                            width: "100%", 
                            height: "12px", 
                            background: "#f0f0f0", 
                            borderRadius: "10px",
                            overflow: "hidden"
                          }}>
                            <div style={{ 
                              width: `${Math.min((results.nutrition.total_calories / 800) * 100, 100)}%`, 
                              height: "100%", 
                              background: "linear-gradient(90deg, #ff6b35, #ff8c42)",
                              transition: "width 0.8s ease",
                              borderRadius: "10px"
                            }}></div>
                          </div>
                        </div>

                        <div style={{ marginBottom: "1.5rem" }}>
                          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                            <span style={{ fontSize: "1rem", fontWeight: "600", color: "#333" }}>💪 Proteine</span>
                            <span style={{ fontSize: "1.1rem", fontWeight: "700", color: "#4CAF50" }}>
                              {results.nutrition.total_protein}g
                            </span>
                          </div>
                          <div style={{ 
                            width: "100%", 
                            height: "12px", 
                            background: "#f0f0f0", 
                            borderRadius: "10px",
                            overflow: "hidden"
                          }}>
                            <div style={{ 
                              width: `${Math.min((results.nutrition.total_protein / 50) * 100, 100)}%`, 
                              height: "100%", 
                              background: "linear-gradient(90deg, #4CAF50, #66BB6A)",
                              transition: "width 0.8s ease",
                              borderRadius: "10px"
                            }}></div>
                          </div>
                        </div>

                        <div style={{ marginBottom: "1.5rem" }}>
                          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                            <span style={{ fontSize: "1rem", fontWeight: "600", color: "#333" }}>🍞 Carbohidrați</span>
                            <span style={{ fontSize: "1.1rem", fontWeight: "700", color: "#2196F3" }}>
                              {results.nutrition.total_carbs}g
                            </span>
                          </div>
                          <div style={{ 
                            width: "100%", 
                            height: "12px", 
                            background: "#f0f0f0", 
                            borderRadius: "10px",
                            overflow: "hidden"
                          }}>
                            <div style={{ 
                              width: `${Math.min((results.nutrition.total_carbs / 100) * 100, 100)}%`, 
                              height: "100%", 
                              background: "linear-gradient(90deg, #2196F3, #42A5F5)",
                              transition: "width 0.8s ease",
                              borderRadius: "10px"
                            }}></div>
                          </div>
                        </div>

                        <div style={{ marginBottom: "1.5rem" }}>
                          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                            <span style={{ fontSize: "1rem", fontWeight: "600", color: "#333" }}>🥑 Grăsimi</span>
                            <span style={{ fontSize: "1.1rem", fontWeight: "700", color: "#FFC107" }}>
                              {results.nutrition.total_fat}g
                            </span>
                          </div>
                          <div style={{ 
                            width: "100%", 
                            height: "12px", 
                            background: "#f0f0f0", 
                            borderRadius: "10px",
                            overflow: "hidden"
                          }}>
                            <div style={{ 
                              width: `${Math.min((results.nutrition.total_fat / 50) * 100, 100)}%`, 
                              height: "100%", 
                              background: "linear-gradient(90deg, #FFC107, #FFD54F)",
                              transition: "width 0.8s ease",
                              borderRadius: "10px"
                            }}></div>
                          </div>
                        </div>

                        <div>
                          <div style={{ display: "flex", justifyContent: "space-between", marginBottom: "0.5rem" }}>
                            <span style={{ fontSize: "1rem", fontWeight: "600", color: "#333" }}>🌾 Fibre</span>
                            <span style={{ fontSize: "1.1rem", fontWeight: "700", color: "#8BC34A" }}>
                              {results.nutrition.total_fiber}g
                            </span>
                          </div>
                          <div style={{ 
                            width: "100%", 
                            height: "12px", 
                            background: "#f0f0f0", 
                            borderRadius: "10px",
                            overflow: "hidden"
                          }}>
                            <div style={{ 
                              width: `${Math.min((results.nutrition.total_fiber / 30) * 100, 100)}%`, 
                              height: "100%", 
                              background: "linear-gradient(90deg, #8BC34A, #9CCC65)",
                              transition: "width 0.8s ease",
                              borderRadius: "10px"
                            }}></div>
                          </div>
                        </div>

                        {/* Buton Download */}
                        <button
                          className="btn btn-primary"
                          onClick={() => {
                            const dataStr = JSON.stringify(results, null, 2);
                            const dataBlob = new Blob([dataStr], { type: 'application/json' });
                            const url = URL.createObjectURL(dataBlob);
                            const link = document.createElement('a');
                            link.href = url;
                            link.download = `smartchef-analiza-${new Date().toISOString().slice(0,10)}.json`;
                            link.click();
                            URL.revokeObjectURL(url);
                          }}
                          style={{ 
                            width: "100%", 
                            marginTop: "2rem",
                            padding: "1rem",
                            fontSize: "1rem"
                          }}
                        >
                          📥 Descarcă Raport JSON
                        </button>
                      </div>
                    </div>
                  )}
                </div>
              )}
            </div>
          </div>
        );
    }
  };

  return renderPage();
}

export default App;
